<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetCodeVO;

trait ThemeAssetCodeAccessor
{
    private ThemeAssetCodeVO $_code;
    public function getCode(): string
    {
        return $this->_code->value();
    }
    public function code(): ThemeAssetCodeVO
    {
        return $this->_code;
    }
    public function isCodeChanged(?self $original = null): bool
    {
        return !$this->_code->equals($original?->_code);
    }
    public function withCode(ThemeAssetCodeVO|string $code): self
    {
        $copy = clone $this;
        $copy->_code = ThemeAssetCodeVO::from($code);
        return $copy;
    }
}
